/* ── 9. 预设提示词：「曝光清单」 关闭条目不灰化 ── */
#completion_prompt_manager #completion_prompt_manager_list li {
    grid-template-columns: minmax(0, 1fr) 126px 52px;
    column-gap: 6px;
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt .prompt_manager_prompt_controls {
    justify-content: flex-end;
    align-items: center;
    gap: 4px;
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
    border: 0;
    border-radius: 11px;
    padding: .55em .7em;
    background-color: var(--cy-cell);
}

#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled {
    border: 0;
    background-color: rgba(169, 178, 255, .10);
}

#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name,
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name .prompt-manager-inspect-action {
    color: var(--cy-ink);
}

#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt .completion_prompt_manager_prompt_name .fa-solid {
    color: var(--cy-mist);
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt span span span {
    opacity: .95;
    filter: none;
    color: var(--cy-hi);
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt .prompt_manager_prompt_tokens {
    font-family: var(--cy-label);
    font-size: 11px;
    color: var(--cy-mist);
}

#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .prompt_manager_prompt_tokens::before {
    content: '未曝光';
    display: block;
    width: fit-content;
    margin: 0 0 2px auto;
    padding: 0 5px;
    white-space: nowrap;
    line-height: 1.5;
    border-radius: 99px;
    font-size: 9px;
    letter-spacing: .12em;
    color: var(--cy-hi);
    box-shadow: inset 0 0 0 1px rgba(220, 225, 255, .6);
}

/* 开关图标 → ✦ 胶囊 */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt span span span.prompt-manager-toggle-action {
    position: relative;
    width: 32px;
    height: 18px;
    border-radius: 99px;
    background-color: rgba(20, 28, 80, .6);
    box-shadow: inset 0 0 0 1px rgba(200, 208, 255, .5);
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt span span span.prompt-manager-toggle-action::before {
    content: '';
    position: absolute;
    top: 2px;
    left: 2px;
    width: 14px;
    height: 14px;
    background-color: var(--cy-hi);
    -webkit-mask: var(--cy-star-outline) center / contain no-repeat;
    mask: var(--cy-star-outline) center / contain no-repeat;
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt span span span.fa-toggle-on {
    background-image: linear-gradient(90deg, #8E99F5, #C9CFFF);
    box-shadow: 0 0 10px var(--cy-glow);
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt span span span.fa-toggle-on::before {
    left: auto;
    right: 2px;
    background-color: var(--cy-deep);
    -webkit-mask-image: var(--cy-star);
    mask-image: var(--cy-star);
}

#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) .prompt-manager-toggle-action {
    color: var(--cy-deep);
}

#completion_prompt_manager .completion_prompt_manager_list_separator hr {
    background-image: none;
    min-height: 0;
}

/* 编辑弹窗（小铅笔）：一切保持原亮度 */
#completion_prompt_manager_popup {
    padding: 54px 1em 1em;
    border: 0;
    border-radius: 0 0 20px 20px;
    background-color: var(--cy-panel-strong);
    box-shadow: 0 0 40px rgba(140, 155, 255, .35), 0 20px 40px rgba(0, 0, 0, .4);
}

#completion_prompt_manager_popup .text_muted,
#completion_prompt_manager_popup label,
#completion_prompt_manager_popup .text_pole,
#completion_prompt_manager_popup textarea {
    opacity: 1;
    filter: none;
    color: var(--cy-ink);
}

#completion_prompt_manager_popup label span {
    font-family: var(--cy-label);
    font-size: 10px;
    text-transform: uppercase;
    letter-spacing: .24em;
    color: var(--cy-mist);
}

/* ── 10. 扩展抽屉：「药剂架」 ────────────── */
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4,
.standoutHeader {
    background-image: none;
    background-color: rgba(20, 28, 80, .42);
    border: 0;
    border-radius: 12px;
    padding: 8px 12px;
}

#extensions_settings .inline-drawer-toggle.inline-drawer-header:hover,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header:hover,
.standoutHeader.inline-drawer-header:hover {
    filter: none;
    background-color: rgba(169, 178, 255, .18);
    box-shadow: 0 0 12px rgba(169, 178, 255, .3);
}

.standoutHeader~.inline-drawer-content {
    border: 0;
    border-radius: 12px;
    background-color: var(--cy-cell);
    padding: 8px 12px;
}

.inline-drawer-icon {
    filter: none;
    color: var(--cy-accent);
}

/* 世界书条目开关 → ✦ 胶囊 */
.world_entry .killSwitch {
    position: relative;
    width: 32px;
    height: 18px;
    flex: none;
    border-radius: 99px;
    background-color: rgba(20, 28, 80, .6);
    box-shadow: inset 0 0 0 1px rgba(200, 208, 255, .5);
}

.world_entry .killSwitch::before {
    content: '';
    position: absolute;
    top: 2px;
    left: 2px;
    width: 14px;
    height: 14px;
    background-color: var(--cy-hi);
    -webkit-mask: var(--cy-star-outline) center / contain no-repeat;
    mask: var(--cy-star-outline) center / contain no-repeat;
}

.world_entry .killSwitch.fa-toggle-on {
    background-image: linear-gradient(90deg, #8E99F5, #C9CFFF);
    box-shadow: 0 0 10px var(--cy-glow);
}

.world_entry .killSwitch.fa-toggle-on::before {
    left: auto;
    right: 2px;
    background-color: var(--cy-deep);
    -webkit-mask-image: var(--cy-star);
    mask-image: var(--cy-star);
}

/* ── 11. 选角色：「相纸册」 ──────────────── */
#rm_print_characters_block .character_select,
#rm_print_characters_block .group_select {
    margin: 0 4px 10px 18px;
    padding: 8px 10px;
    border-radius: 12px;
    background-color: var(--cy-cell);
}

.character_select .avatar,
.group_select .avatar,
.avatar-container .avatar {
    padding: 2.5px;
    background-color: var(--cy-hi);
    box-shadow: 0 0 10px rgba(169, 178, 255, .6), 0 4px 12px rgba(0, 0, 0, .4);
}

#rm_print_characters_block .character_select .avatar,
#rm_print_characters_block .group_select .avatar {
    margin-left: -26px;
}

.character_select .avatar img,
.avatar-container .avatar img {
    width: 100%;
    height: 100%;
    border: 0;
    box-shadow: none;
}

body.charListGrid #rm_print_characters_block .character_select,
body.charListGrid #rm_print_characters_block .group_select {
    margin: 4px;
}

body.charListGrid #rm_print_characters_block .character_select .avatar,
body.charListGrid #rm_print_characters_block .group_select .avatar {
    margin-left: 0;
}

.ch_name {
    font-family: var(--cy-serif);
    font-weight: 600;
    letter-spacing: .08em;
    color: #F2F4FF;
}

.ch_description {
    font-family: var(--cy-serif);
    color: #C9D0F2;
}

.bogus_folder_select:hover,
.character_select:hover,
.avatar-container:hover {
    background-color: rgba(169, 178, 255, .18);
}

/* 收藏 = 实心 ✦（替换金色描边） */
.character_select.is_fav .avatar,
.group_select.is_fav .avatar,
.group_member.is_fav .avatar,
.avatar.is_fav {
    outline: 0;
}

.character_select.is_fav .ch_name,
.group_select.is_fav .ch_name,
.group_member.is_fav .ch_name {
    color: #F2F4FF;
}

#rm_print_characters_block .character_select.is_fav .character_select_container::after {
    content: '';
    position: absolute;
    top: 2px;
    right: 2px;
    width: 14px;
    height: 14px;
    background-color: var(--cy-hi);
    -webkit-mask: var(--cy-star) center / contain no-repeat;
    mask: var(--cy-star) center / contain no-repeat;
    filter: drop-shadow(0 0 4px var(--cy-glow));
}

.tags_inline .tag {
    border: 0;
    border-radius: 99px;
    padding: 0 8px;
}

/* ── 12. 选 user：「显影者」 ─────────────── */
.avatar-container {
    margin-bottom: 8px;
    border-radius: 12px;
    background-color: var(--cy-cell);
}

.avatar-container.selected {
    border-color: transparent;
    isolation: isolate;
    background-color: rgba(120, 135, 230, .38);
    box-shadow: 0 0 22px rgba(169, 178, 255, .45);
}

.avatar-container.selected .avatar::before {
    content: '';
    position: absolute;
    left: 50%;
    top: 50%;
    width: 170%;
    height: 170%;
    transform: translate(-50%, -50%);
    background-color: var(--cy-hi);
    -webkit-mask: var(--cy-star) center / contain no-repeat;
    mask: var(--cy-star) center / contain no-repeat;
    filter: drop-shadow(0 0 10px rgba(200, 208, 255, 1)) drop-shadow(0 0 24px rgba(150, 165, 255, .9));
    z-index: -1;
}

.avatar-container .avatar {
    position: relative;
}

.avatar-container.selected .character_name_block::after {
    content: '当前显影者';
    font-family: var(--cy-label);
    font-size: 9px;
    letter-spacing: .2em;
    color: var(--cy-hi);
    white-space: nowrap;
}

.avatar-container.default_persona .avatar {
    outline: 2px solid var(--cy-accent);
}

/* ── 13. 弹窗 ───────────────────────────── */
.popup {
    background-color: var(--cy-panel-strong);
    border: 0;
    border-radius: 16px;
    color: var(--cy-ink);
    box-shadow: 0 0 40px rgba(140, 155, 255, .35), 0 20px 40px rgba(0, 0, 0, .4);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
}
